const handlers={stock_preparation:stock,dissolution:dissolve,stirring:stir,solution_addition:addition,dropwise_addition:addition,heating,cooling,ice_bath_cooling:cooling,ice_bath_crystallization:cooling,filtration:filter,hot_filtration:filter,vacuum_evaporation:vacEvap,rotary_evaporation:rotary,centrifugation:centrifuge,sonication:sonicate,solvent_sonication:sonicate,washing_sonication_centrifugation:sonicate,water_quench:quench,vacuum_drying:dry,recrystallization:recrystallize,solvent_drying:solventDry,ion_exchange:waterTreatment,charcoal_purification:waterTreatment,vacuum_distillation:distill,ampule_opening:ampules,grid_cleaning:cleanGrid,drop_casting:cast,air_drying:airDry,tem_calibration:calibrate,tem,nmr_sample_preparation:sampleNmr,nmr,deuterium_exchange:exchange,kbr_pellet_preparation:pellet,ftir,optical_sample_preparation:sampleOptical,uv_visible:optical,control_exposure:exposure,acyl_chloride_exposure:exposure,prolonged_surface_reaction:exposure,aqueous_workup:workup};
export function buildVeinotScene(o,r){if(!r?.sources?.some(s=>s.doi===DOI)||!/^veinot-1997-/.test(r.record_id)||!handlers[o?.action])return null;return {kind:o.action,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 388" role="img" aria-label="${esc(o.label)} — explanatory process diagram" style="width:100%;height:auto;font-family:Arial,sans-serif;fill:${C.ink}"><title>${esc(o.label)}</title><desc>Source-specific explanatory apparatus and material flow; geometry, particle count, color and surface motif are illustrative. No experimental atomic model, diffraction pattern or spectrum is generated.</desc>${handlers[o.action](o,r)}</svg>`,caption:'Source-specific explanatory diagram. Vessel geometry, colors, particle counts and connection motifs are illustrative. Source conditions and limits are listed alongside; inherited 2b–e steps remain marked. No measured CdS phase, atomic coordinates or complete surface coverage is asserted.'};}
export function createVeinotArt(o,r){const s=buildVeinotScene(o,r);if(!s)return null;const n=document.createElement('div');n.className='protocol-art protocol-art-veinot';n.dataset.scene='veinot-'+s.kind;n.style.height='auto';n.innerHTML=s.svg;return n;}
